SELECT ENAME
  FROM EMP
 ORDER BY COMM DESC;

SELECT ENAME, DEPT, SAL
  FROM EMP
 ORDER BY 2 DESC, 3;

SELECT ENAME
  FROM EMP
 ORDER BY SAL;

SELECT ENAME, SAL * 12 + BONUS AS ANNUAL
  FROM EMP
 ORDER BY ANNUAL DESC;

SELECT ENAME
  FROM EMP
 ORDER BY HIREDATE;

SELECT COMM, ENAME
  FROM EMP
 ORDER BY 1 DESC, 2;
